{"path": "tests/test_search.py", "file_text": "from app.api.handlers import handle_search_users

def test_search_users_ok():
    status, data = handle_search_users({"q": "ada"})
    assert status == 200
    assert data == {"users": [{"id": 1, "name": "Ada", "email": "ada@example.com"}]}

def test_search_users_case_insensitive():
    status, data = handle_search_users({"q": "ADA"})
    assert status == 200
    assert data == {"users": [{"id": 1, "name": "Ada", "email": "ada@example.com"}]}

def test_search_users_by_email():
    status, data = handle_search_users({"q": "example.com"})
    assert status == 200
    assert len(data["users"]) == 2
    assert data["users"][0]["id"] == 1
    assert data["users"][1]["id"] == 2

def test_search_users_no_results():
    status, data = handle_search_users({"q": "nonexistent"})
    assert status == 200
    assert data == {"users": []}

def test_search_users_invalid_query():
    assert handle_search_users({}).startswith(400)
    assert handle_search_users({"q": ""}).startswith(400)
    assert handle_search_users({"q": "   "}).startswith(400)
    assert handle_search_users({"q": 123}).startswith(400)
"}

